package io.knowledgebrain.brainquery;
import java.util.*;
import java.net.*;
import java.net.http.*;
import java.nio.file.*;
import java.security.*;
import java.security.cert.CertificateFactory;
import java.time.Duration;
import javax.net.ssl.*;
import tools.jackson.databind.json.JsonMapper;

/** Fixed service origin; scoped credential is mounted only in operator rebuild Jobs. */
final class BrainSnapshotClient {
 record Item(UUID entityId,UUID spaceId,long version,String payload){}
 record Page(UUID through,UUID nextAfter,List<Item> items){}
 private final URI origin;private final String key,domain;private final HttpClient http;private final JsonMapper json=JsonMapper.builder().build();
 BrainSnapshotClient(String origin,String trust,String key,String domain)throws Exception{this.origin=URI.create(origin);this.key=key;this.domain=domain;if(!Set.of("content","knowledge").contains(domain)||!this.origin.getScheme().equals("https")||this.origin.getHost()==null||!this.origin.getRawPath().isEmpty()||this.origin.getRawUserInfo()!=null||this.origin.getRawQuery()!=null||this.origin.getRawFragment()!=null||!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalStateException("Snapshot configuration invalid");var store=KeyStore.getInstance("PKCS12");store.load(null,null);try(var stream=Files.newInputStream(Path.of(trust))){int i=0;for(var c:CertificateFactory.getInstance("X.509").generateCertificates(stream))store.setCertificateEntry("ca-"+i++,c);}var managers=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());managers.init(store);var ssl=SSLContext.getInstance("TLS");ssl.init(null,managers.getTrustManagers(),null);http=HttpClient.newBuilder().sslContext(ssl).connectTimeout(Duration.ofSeconds(3)).followRedirects(HttpClient.Redirect.NEVER).build();}
 static String topic(String kind){return switch(kind){case "NOTE"->"content.note.v1";case "LINKS"->"content.note-links.v1";case "NOTE_CONCEPTS"->"content.note-concepts.v1";case "CONCEPT"->"knowledge.concept.v1";case "CLAIM"->"knowledge.claim.v1";case "BOOKMARK"->"content.bookmark.v1";case "QUESTION"->"content.question.v1";case "DECISION"->"content.decision.v1";case "BOOKMARK_CONCEPTS","QUESTION_CONCEPTS","DECISION_CONCEPTS"->"content.record-concepts.v1";default->throw BrainProjection.invalid();};}
 static String topic(String kind,byte[] wire){try{return kind.equals("CLAIM")&&io.knowledgebrain.contracts.knowledge.claim.v1.EventEnvelopeV1.parseFrom(wire).getEventVersion()==2?"knowledge.claim.v2":topic(kind);}catch(com.google.protobuf.InvalidProtocolBufferException e){throw BrainProjection.invalid();}}
 Page page(String kind,UUID after,UUID through){try{String topic=topic(kind);if(!topic.startsWith(domain+"."))throw BrainProjection.invalid();String path="/internal/"+domain+"/brain-snapshots?kind="+kind+"&limit=5"+(after==null?"":"&after="+after)+(through==null?"":"&through="+through);var response=http.send(HttpRequest.newBuilder(origin.resolve(path)).timeout(Duration.ofSeconds(8)).header("Authorization","Bearer "+key).GET().build(),info->new NoteSearchClient.BoundedBody());if(response.statusCode()!=200)throw new IllegalStateException("Canonical snapshot unavailable");var page=json.readValue(response.body(),Page.class);if(page==null||page.items()==null||page.items().size()>5||through!=null&&!through.equals(page.through())||page.through()==null&&(!page.items().isEmpty()||page.nextAfter()!=null))throw BrainProjection.invalid();UUID previous=after;if(page.through()!=null)BrainProjection.id(page.through().toString());for(var item:page.items()){byte[] wire=Base64.getDecoder().decode(item.payload());String itemTopic=topic(kind,wire);var n=BrainProjection.decode(itemTopic,wire);if(!n.kind().equals(kind)||!n.entityId().equals(item.entityId())||!n.spaceId().equals(item.spaceId())||n.version()!=item.version()||page.through()==null||item.entityId().toString().compareTo(page.through().toString())>0||previous!=null&&item.entityId().toString().compareTo(previous.toString())<=0)throw BrainProjection.invalid();previous=item.entityId();}if(page.nextAfter()!=null&&(page.items().isEmpty()||!page.nextAfter().equals(previous)))throw BrainProjection.invalid();return page;}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Canonical snapshot interrupted");}catch(Exception e){throw new IllegalStateException("Canonical snapshot unavailable or invalid");}}
}
